describe('Video Captions Accessibility', () => {
  beforeEach(() => {
    cy.visit('/videos');
    cy.viewport(1280, 720);
  });

  it('should display captions toggle button on video player', () => {
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="captions-toggle-btn"]').should('be.visible');
    cy.get('[data-testid="captions-toggle-btn"]').should('have.attr', 'aria-label', 'Toggle captions');
  });

  it('should enable captions when toggle button is clicked', () => {
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="captions-toggle-btn"]').click();
    cy.get('[data-testid="captions-container"]').should('be.visible');
    cy.get('[data-testid="captions-text"]').should('contain.text', '');
    cy.get('[data-testid="captions-toggle-btn"]').should('have.attr', 'aria-pressed', 'true');
  });

  it('should disable captions when toggle button is clicked again', () => {
    cy.get('[data-testid="captions-toggle-btn"]').click();
    cy.get('[data-testid="captions-container"]').should('be.visible');
    cy.get('[data-testid="captions-toggle-btn"]').click();
    cy.get('[data-testid="captions-container"]').should('not.be.visible');
    cy.get('[data-testid="captions-toggle-btn"]').should('have.attr', 'aria-pressed', 'false');
  });

  it('should display captions synchronized with video playback', () => {
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="captions-toggle-btn"]').click();
    cy.get('[data-testid="play-btn"]').click();
    cy.wait(2000);
    cy.get('[data-testid="captions-text"]').should('be.visible');
    cy.get('[data-testid="captions-text"]').invoke('text').should('not.be.empty');
  });

  it('should support multiple caption languages', () => {
    cy.get('[data-testid="captions-toggle-btn"]').click();
    cy.get('[data-testid="caption-language-selector"]').should('be.visible');
    cy.get('[data-testid="caption-language-selector"]').click();
    cy.get('[data-testid="language-option"]').should('have.length.greaterThan', 1);
    cy.get('[data-testid="language-option"]').first().click();
    cy.get('[data-testid="captions-text"]').should('be.visible');
  });

  it('should persist caption preference in user settings', () => {
    cy.get('[data-testid="captions-toggle-btn"]').click();
    cy.get('[data-testid="captions-toggle-btn"]').should('have.attr', 'aria-pressed', 'true');
    cy.reload();
    cy.get('[data-testid="captions-container"]').should('be.visible');
    cy.get('[data-testid="captions-toggle-btn"]').should('have.attr', 'aria-pressed', 'true');
  });

  it('should handle videos without captions gracefully', () => {
    cy.get('[data-testid="video-player"]').eq(1).should('be.visible');
    cy.get('[data-testid="video-player"]').eq(1).within(() => {
      cy.get('[data-testid="captions-toggle-btn"]').should('be.disabled');
      cy.get('[data-testid="captions-unavailable-badge"]').should('be.visible');
    });
  });

  it('should have proper contrast for caption text', () => {
    cy.get('[data-testid="captions-toggle-btn"]').click();
    cy.get('[data-testid="play-btn"]').click();
    cy.wait(2000);
    cy.get('[data-testid="captions-text"]').should('have.css', 'color');
    cy.get('[data-testid="captions-text"]').should('have.css', 'background-color');
    cy.get('[data-testid="captions-text"]').should('have.css', 'font-size');
  });

  it('should allow caption text size customization', () => {
    cy.get('[data-testid="captions-toggle-btn"]').click();
    cy.get('[data-testid="caption-settings-btn"]').click();
    cy.get('[data-testid="text-size-slider"]').should('be.visible');
    cy.get('[data-testid="text-size-slider"]').invoke('val', 150).trigger('change');
    cy.get('[data-testid="captions-text"]').should('have.css', 'font-size');
  });
});
